export async function handler(context, parameters) {
  const delay = parameters.delay_ms || 3000;
  const callbackUrl = context.callbackUrl;
  const resultData = parameters.result_data || { status: "completed", answer: 42 };

  if (!callbackUrl) {
    return { success: false, error: "No callbackUrl provided in context" };
  }

  console.log(`Async tool: will callback in ${delay}ms to ${callbackUrl}`);

  // Fire-and-forget: delayed callback
  setTimeout(async () => {
    try {
      const res = await fetch(callbackUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(resultData),
      });
      console.log(`Callback sent: ${res.status}`);
    } catch (err) {
      console.error(`Callback failed: ${err.message}`);
    }
  }, delay);

  return {
    success: true,
    output: {
      async: true,
      message: `Processing started. Callback in ${delay}ms.`,
      callbackUrl: callbackUrl
    }
  };
}
